import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import { Permission, PermissionsAPI } from '@imunify360-api/permissions';
import { AuthState } from 'app/services/auth-state';
import {
    Observable,
    map,
    tap,
    catchError,
    of,
    noop,
    take,
    combineLatest,
    filter,
    switchMap,
} from 'rxjs';
import { Router } from '@angular/router';
import { ModalService } from 'app/utils/modals/modal.service';
import { AppState } from 'app/core/app.service';
import { AgentStatus } from '@imunify360-api/misc';


@Injectable()
export class PermissionsService {
    list: Observable<Array<Permission>>;
    MS_ON_DEMAND_SCAN = this.has(Permission.MS_ON_DEMAND_SCAN);
    MS_CONFIG_DEFAULT_ACTION_EDIT = this.has(Permission.MS_CONFIG_DEFAULT_ACTION_EDIT);
    MS_CLEAN = this.has(Permission.MS_CLEAN);
    MS_PATCH_HAS_SUBSCRIBE = this.has(Permission.MS_PATCH_HAS_SUBSCRIBE);
    MS_PATCH_ENABLED = this.has(Permission.MS_PATCH_ENABLED);
    MS_CLEAN_REQUIRES_MYIMUNIFY_PROTECTION = this.has(Permission.MS_CLEAN_REQUIRES_MYIMUNIFY_PROTECTION);
    WP_WAF_EDIT = this.has(Permission.WP_WAF_EDIT);
    WP_WAF_RULES_EDIT = this.has(Permission.WP_WAF_RULES_EDIT);

    get = this.xhr.rx(PermissionsAPI.list);

    constructor(
        public xhr: XHR,
        public authState: AuthState,
        public modalService: ModalService,
        public router: Router,
        private appState: AppState,
    ) {
        const agentStatus$ = this.appState.rpcReady$
            .pipe(
                filter(value => !!value),
                take(1),
                switchMap(() => this.appState.imunifyStatus)
            );

        combineLatest({ agentStatus: agentStatus$, logged: this.authState.loginChange })
            .subscribe(({agentStatus, logged}) => {
                // we don't need to request permissions, if agent is not OK
                if (agentStatus !== AgentStatus.OK) {
                    return;
                }
                if (!logged) {
                    this.authState.resetPermissions();
                    return;
                }
                if (!this.authState.permissionRequested) {
                    this.authState.permissionRequested = true;
                    this.requestPermissions();
                }
            });
    }

    has(item: Permission): Observable<boolean> {
        return this.authState.listPermission$.pipe(
            map((list) => list.includes(item),
        ));
    }

    async openUpgradeWarning(UpgradeWarningModalComponent) {
        if (await this.modalService.open(UpgradeWarningModalComponent, {data: {}})) {
            await this.router.navigate(['/', IMUNIFY_PACKAGE, 'admin', 'upgrade']);
        }
    }

    private requestPermissions(): void {
        this.get().pipe(
            take(1),
            tap(res => {
                const items = res.data?.items?.length ? res.data.items : [];
                this.authState.listPermission$.next(items);
            }),
            catchError(() => {
                this.authState.resetPermissions();
                return of(null);
            }),
        ).subscribe({ next: noop, error: noop });
    }
}
