import { Injectable } from '@angular/core';
import { Observable, forkJoin, map, catchError, of } from 'rxjs';
import { XHR } from 'app/utils/xhr/xhr';
import { RequestsState } from 'app/services/requests-state';
import { Panel } from 'app/utils/panel';
import { UamAPI, UamRule, UamStatus } from '@imunify360-api/uam';

@Injectable({ providedIn: 'root' })
export class UamService {
    private settingsGet = this.xhr.rx(UamAPI.settingsGet, false, false);
    private visibilityGet = this.xhr.rx(UamAPI.visibilityGet, false, false);
    private domainsList = this.xhr.rx(UamAPI.domains, false, false);
    private rulesList = this.xhr.rx(UamAPI.list);
    list = this.xhr.wrap(this.rulesList, UamRule);
    counters = this.xhr.rx(UamAPI.counters, false, false);
    test = this.xhr.rx(UamAPI.test);
    add = this.xhr.rx(UamAPI.add);
    edit = this.xhr.rx(UamAPI.edit);
    remove = this.xhr.rx(UamAPI.delete);
    settingsSet = this.xhr.rx(UamAPI.settingsSet);
    visibilitySet = this.xhr.rx(UamAPI.visibilitySet);

    constructor(
        private xhr: XHR,
        private requestsState: RequestsState,
        private panel: Panel,
    ) {}

    getStatus(): Observable<UamStatus | null> {
        return this.fetchStatus().pipe(catchError(() => of(null)));
    }

    cachedStatus(): Observable<UamStatus | null> {
        if (!this.panel.isCpanel) {
            return of(null);
        }
        return this.requestsState
            .makeCachedRequest(() => this.fetchStatus(), 'uamStatus')
            .pipe(catchError(() => of(null)));
    }

    showAdminTab(): Observable<boolean> {
        return this.cachedStatus().pipe(map(status => !!status));
    }

    showClientTab(): Observable<boolean> {
        return this.cachedStatus().pipe(map(status => !!status?.allowed_for_users));
    }

    domains(): Observable<string[] | null> {
        return this.domainsList().pipe(
            // A panel that cannot enumerate domains answers with an empty list
            // rather than an error; that has to read as "unavailable", or the
            // picker offers nothing and its in-list validator rejects every
            // value.
            map(response => response.data.items?.length ? response.data.items : null),
            catchError(() => of(null)),
        );
    }

    private fetchStatus(): Observable<UamStatus> {
        return forkJoin([this.settingsGet(), this.visibilityGet()]).pipe(
            map(([settings, visibility]) => ({
                enabled: !!settings.data.enabled,
                allowed_for_users: !!visibility.data.allowed_for_users,
            })),
        );
    }
}
