import { NAVBAR_TABS, NAVBAR_ITEMS } from 'app/components/nav-root/navbar-items.enum';
import { MALWARE_TABS } from 'app/components/malware/malware-tabs.enum';
import { PROACTIVE_DEFENCE_TABS } from 'app/components/proactive-defense/proactive-defence-tabs.enum';
import { ProactiveDefenseActions } from 'app/components/proactive-defense/proactive-defense-actions.enum';
import { MalwareActionNames } from 'app/components/malware/actions/misc';
import { CMS_PROTECTION_TABS } from 'app/components/cms-protection/cms-protection-tabs.enum';
import { WEBSHIELD_TABS } from 'app/components/webshield/webshield-tabs.enum';

export function isNavbarItemAllowed(item: NAVBAR_ITEMS): boolean {
    if (typeof I360_ALLOWED_ITEMS === 'undefined') return true;

    return !!I360_ALLOWED_ITEMS?.[item];
}

type SUB_TABS = PROACTIVE_DEFENCE_TABS | MALWARE_TABS | CMS_PROTECTION_TABS | WEBSHIELD_TABS;

export function isSubTabAllowed(tab: NAVBAR_TABS, subTab: SUB_TABS): boolean {
    if (typeof I360_ALLOWED_ITEMS === 'undefined') return true;
    if (I360_ALLOWED_ITEMS?.[tab] === true) return true;

    return !!I360_ALLOWED_ITEMS?.[tab]?.[subTab];
}

export function getFirstAllowedMalwareTab(): MALWARE_TABS | null {
    for (const value of Object.values(MALWARE_TABS)) {
        if (isSubTabAllowed(NAVBAR_TABS.MalwareScanner, value)) {
            return value;
        }
    }

    return null;
}

const defaultConfig: ISubTabItemsConfig = {
    hideFilters: false,
    hideCheckboxes: false,
};

export function getSubTabItemsConfig(tab: NAVBAR_TABS, subTab: MALWARE_TABS | PROACTIVE_DEFENCE_TABS): ISubTabItemsConfig {
    if (typeof I360_ALLOWED_ITEMS === 'undefined') return defaultConfig;

    const tabConfig = I360_ALLOWED_ITEMS?.[tab]?.[subTab];

    if (tabConfig && tabConfig !== true) {
        return {
            hideFilters: tabConfig?.hideFilters === true,
            hideCheckboxes: tabConfig?.hideCheckboxes === true,
            allowedActions: tabConfig?.allowedActions,
        };
    }

    return defaultConfig;
}

export function isActionAllowed(tabConfig: ISubTabItemsConfig, actionName: ProactiveDefenseActions | MalwareActionNames): boolean {
    if (typeof I360_ALLOWED_ITEMS === 'undefined') return true;
    if (tabConfig?.allowedActions?.includes) {
        return tabConfig.allowedActions.includes(actionName);
    }

    return true;
}

/**
 * Returns true unless WORDPRESS.waf_enabled is explicitly false in the
 * supplied config object.  Handles missing WORDPRESS section or missing
 * waf_enabled key by defaulting to true (WAF on).
 */
export function isWafEnabledInConfig(config: any): boolean {
    return config?.WORDPRESS?.waf_enabled !== false;
}

export function isProactiveViewFileOnly(tabConfig: ISubTabItemsConfig): boolean {
    if (tabConfig?.allowedActions?.includes && tabConfig.allowedActions.includes(ProactiveDefenseActions.ViewFile)) {
        return !([ProactiveDefenseActions.IgnoreDetected, ProactiveDefenseActions.IgnoreAll]
            .some(action => tabConfig.allowedActions?.includes(action)));
    }

    return false;
}

