import { Injectable } from '@angular/core';


export const TABLE_COLUMN_CONFIGURATION_NAME = 'I360_TABLE_COLUMN_CONFIGURATION_NAME';

@Injectable({
    providedIn: 'root',
})
export class I360ColumnConfigurationService {
    private tableData: Record<string, any> = {};

    setItems(tableName: string, data: any): void {
        this.tableData[tableName] = data;
        this.syncWithLocalStorage();
    }

    getStoreData(tableName: string): any {
        if (!this.tableData[tableName]) {
            const storeData = this.loadFromLocalStorage();
            this.tableData = {...storeData}; // Сохраняем кэш данных
        }
        return this.tableData[tableName] || [];
    }

    clearTableData(tableName: string): void {
        delete this.tableData[tableName];
        this.syncWithLocalStorage();
    }

    private syncWithLocalStorage(): void {
        try {
            localStorage.setItem(
                TABLE_COLUMN_CONFIGURATION_NAME,
                JSON.stringify(this.tableData),
            );
        } catch (error) {
            console.error('Error saving to localStorage:', error);
        }
    }

    private loadFromLocalStorage(): Record<string, any> {
        try {
            return JSON.parse(
                localStorage.getItem(TABLE_COLUMN_CONFIGURATION_NAME) || '{}',
            );
        } catch (error) {
            console.error('Error loading from localStorage:', error);
            return {};
        }
    }
}
