import {
    AfterViewInit, ChangeDetectorRef,
    Component, Input, ViewChild,
} from '@angular/core';
import { WidgetDirective } from 'app/utils/table/widgets/widget';
import { I360DropdownDirective } from 'app/utils/table/widgets/headers/dropdown-directive';


@Component({
    selector: 'i360-dropdown-widget-header',
    template: `
        <div class="dropdown {{widget.debugCssClass}}"
            [hidden]="!widget.visible || !widget.visibleByDefault"
            i360-dropdown>
            <button type="button" class="b_btn dropdown-toggle"
                    aria-haspopup="true" aria-expanded="false">
                {{ widget.title | translate }}
            </button>
            <ul *ngIf="dropdownReady" class="b_dropdown-menu dropdown-menu">
                <li *ngFor="let item of widget.availableValues|keys">
                    <a (click)="widget.setValue(item.key, true)"
                       [class.selected]="isSelected(item.key)">
                        {{ item.value | translate }}
                    </a>
                </li>
            </ul>
        </div>`,
})
export class DropdownWidgetHeaderComponent implements AfterViewInit {
    @Input() widget: WidgetDirective;
    @ViewChild(I360DropdownDirective, {static: true}) dropdown: I360DropdownDirective;

    dropdownReady = false;
    constructor(
        private cdRef : ChangeDetectorRef
    ) {}

    isSelected(key: string) {
        if (!this.widget?.value) {
            return this.widget?.defaultValue === key
        }
        return this.widget?.hasValue(key)
    }
    ngAfterViewInit(): void {
        this.dropdownReady = true;
        this.cdRef.detectChanges();
    }
}
