import { ModalEntry } from 'app/utils/modals/entry';
import { Component, Inject } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { ColumnComponent } from 'app/utils/table/column.component';
import { I360FormBuilder } from 'app/utils/validator/form-builder';


type ConfigColumns = { selected: string[], allColumns: ColumnComponent[] }

@Component({
    templateUrl: './i360-config-columns.modal.component.html',
    styleUrls: ['./i360-config-columns.modal.component.scss'],
})
export class I360ConfigColumnsModalComponent extends ModalEntry<ConfigColumns, false> {
    form = this.formBuilder.group(
        this.data.allColumns.filter((col) => !!col.bodyField)
            .reduce((controls, column) => {
                controls[column.bodyField] = this.formBuilder.control(
                    {
                        value: !column.configurable || this.data.selected.includes(column.bodyField),
                        disabled: !column.configurable,
                    },
                );
                return controls;
            }, {}),
    );

    constructor(
        private dialogRef: MatDialogRef<I360ConfigColumnsModalComponent>,
        private formBuilder: I360FormBuilder,
        @Inject(MAT_DIALOG_DATA) public data: ConfigColumns,
    ) {
        super();
    }
}
