import {
    AfterContentInit,
    Component, EventEmitter,
    Input,
    Output, QueryList, TemplateRef,
    ViewChild,
} from '@angular/core';
import { ModalService } from 'app/utils/modals/modal.service';
import { I360ColumnConfigurationService } from 'app/utils/table/i360-column-configuration/i360-column-configuration.service';
import { ColumnComponent } from 'app/utils/table/column.component';
import { I360ConfigColumnsModalComponent } from 'app/utils/table/i360-column-configuration/modal/i360-config-columns.modal.component';

@Component({
    selector: 'i360-column-configuration',
    template: `
     <ng-template #configTemplate>
         <span class="i360-column-configuration" (click)="updateFields()">
            <mat-icon  [matTooltip]="'table.dynamicColumns' | translate"
                       svgIcon="configuration">
            </mat-icon>
         </span>
     </ng-template>`,
    styleUrls: ['./i360-column-configuration.component.scss'],
})
export class I360ColumnConfigurationComponent implements AfterContentInit {
    @ViewChild('configTemplate', { static: false }) configTemplate: TemplateRef<any>;
    @Input() columns: QueryList<ColumnComponent>;
    @Input() tableName: string;
    @Output() selectedColumn = new EventEmitter();

    constructor(
        private modalService: ModalService,
        private columnConfigurationService: I360ColumnConfigurationService,
    ) {}

    ngAfterContentInit(): void {
        this.selectedColumn.emit(this.columnConfigurationService.getStoreData(this.tableName))
    }

    async updateFields() {
        const columnst: ColumnComponent[] = this.columns.filter((col) => {
            // for configuration need the bodyField
            return !!col.bodyField
        })
        const modalResult = await this.modalService.open(I360ConfigColumnsModalComponent,{
            data: {
                selected: this.columnConfigurationService.getStoreData(this.tableName),
                allColumns: columnst
            }});
        if (modalResult) {
            const selectedFields = Object.entries(modalResult)
              .filter(([key, value]) => value)
              .map(([key]) => key);
            this.columnConfigurationService.setItems(this.tableName, selectedFields)
            this.selectedColumn.emit(selectedFields);
        }
    }
}
