import { Injectable } from '@angular/core';
import { firstValueFrom, catchError, of } from 'rxjs';
import { MatDialogConfig } from '@angular/material/dialog';
import { FileService } from 'app/services/file';
import { MaliciousItem, MdsResourceTypeMaliciousList } from '@imunify360-api/malicious';
import { ModalService } from 'app/utils/modals/modal.service';
import { TranslateService } from 'app/utils/translate/translate.service';
import {
    FileViewerComponent,
    FileViewerOptions,
} from 'app/utils/file-viewer/file-viewer.component';

@Injectable()
export class FileViewerService {
    constructor(
        private fileService: FileService,
        private modalService: ModalService,
        private translateService: TranslateService,
    ) {}

    async openFileViewerWithDiff(file: MaliciousItem): Promise<void | any> {
        try {
            const fileResponse = await firstValueFrom(this.fileService.load({path: file.file}));

            if (fileResponse) {
                const diffResponse = await firstValueFrom(
                    this.fileService.loadDiff(file.id).pipe(catchError(() => of(null))),
                );
                const options = {
                    data: {
                        path: file.file,
                        chunk: fileResponse.data.data.chunk,
                        limit: fileResponse.data.data.limit,
                        size: fileResponse.data.data.size,
                        ...(diffResponse ? {diff: diffResponse?.data?.diff} : {}),
                    },
                };
                return this.openFileDialog(options);
            }
        } catch (e) {
        }
    }

    async openFileViewer(params: string | FileViewerOptions): Promise<void | any> {
        try {
            let options;
            if (typeof params === 'string') {
                const path = params;
                const {chunk, limit, size} = (await firstValueFrom(this.fileService.load({path}))).data.data;
                options = {
                    data: {
                        path, chunk, limit, size,
                    },
                };
            } else {
                options = {
                    data: params,
                };
            }
            return this.openFileDialog(options);
        } catch (e) { }
    }

    async openDBViewer(param: MdsResourceTypeMaliciousList): Promise<void|any> {
        try {
            let snippet = param.snippet as string;

            try {
                snippet = decodeURIComponent(param.snippet as string);
            } catch (e) {}
            const parser = new DOMParser();
            const decodedString = parser.parseFromString(snippet, 'text/html')
                .documentElement.textContent;
            const dbNameLabel = this.translateService.translate.instant('malware.dbName');
            const appRootLabel = this.translateService.translate.instant('malware.appRoot');
            const options = {
                data: {
                    path: `//${param.db_host}:${param.db_port}/${param.db_name}/${param.app_name}`,
                    subTitle: `${appRootLabel}: ${param.file}`,
                    title: `${dbNameLabel}: ${param.db_name}`,
                    chunk: decodedString || param.snippet || '',
                    limit: 0,
                    size: 0,
                },
            };
            return this.openFileDialog(options);
        } catch (e) {}
    }

    openFileDialog(options: MatDialogConfig<FileViewerOptions>): Promise<boolean> {
        this.modalService.addPanelClass(options, 'i360-file-viewer-panel');
        return this.modalService.open(FileViewerComponent, options);
    }
}
