import { Component, OnDestroy, OnInit, Optional, SkipSelf } from '@angular/core';
import { AbstractControl, ControlContainer, FormControl, FormGroup } from '@angular/forms';
import { Subject, identity, map, takeUntil } from 'rxjs';
import { PermissionsService } from 'app/services/permissions';
import { ConfigRef } from 'app/core/config-ref';
import { AiBotProtectionPreset } from '@imunify360-api/settings';

@Component({
    selector: 'i360-wordpress-section',
    templateUrl: './wordpress-section.component.html',
    viewProviders: [{
        provide: ControlContainer,
        useFactory: identity,
        deps: [[new SkipSelf, ControlContainer]],
    }]
})
export class WordpressSectionComponent implements OnInit, OnDestroy {
    private destroyed = new Subject<void>();
    private isDestroyed = false;
    private savedWafEnabled = true;

    readonly wafState$ = this.permissions.WP_WAF_EDIT.pipe(
        map(canEdit => ({
            disabled: !canEdit,
            warning: !canEdit ? 'warning.set_by_admin' as const : false as const,
        })),
    );

    constructor(
        public permissions: PermissionsService,
        private controlContainer: ControlContainer,
        @Optional() private configRef: ConfigRef | null,
    ) {}

    private get wordpressGroup(): FormGroup | null {
        return (this.controlContainer.control?.get('WORDPRESS') as FormGroup | null) ?? null;
    }

    get hasInstallControl(): boolean {
        return !!this.wordpressGroup?.get('security_plugin_enabled');
    }

    get installPluginEnabled(): boolean {
        return !!this.wordpressGroup?.get('security_plugin_enabled')?.value;
    }

    get wafEnabled(): boolean {
        return !!this.wordpressGroup?.get('waf_enabled')?.value;
    }

    get hasWafDefaultControl(): boolean {
        return !!this.wordpressGroup?.get('waf_default');
    }

    get hasAiBotControl(): boolean {
        return !!this.wordpressGroup?.get('ai_bot_protection');
    }

    get hasAiBotPresetControl(): boolean {
        return !!this.wordpressGroup?.get('ai_bot_protection_preset');
    }

    get aiBotEnabled(): boolean {
        return !!this.wordpressGroup?.get('ai_bot_protection')?.value;
    }

    get hasAiBotDefaultControl(): boolean {
        return !!this.wordpressGroup?.get('ai_bot_protection_default');
    }

    // Reflects the persisted server state, not a pending edit: only warn once the
    // off state is actually saved, so unchecking the box does not flash a "disabled
    // for all accounts" message before the admin commits the change.
    get adminWafWarning(): string | false {
        return this.hasInstallControl && this.installPluginEnabled
            && !this.wafEnabled && !this.savedWafEnabled
            ? 'settings.general.wordPress.waf.warningOff'
            : false;
    }

    ngOnInit() {
        const wpGroup = this.wordpressGroup;
        if (!wpGroup) return;

        const installControl = wpGroup.get('security_plugin_enabled');
        const wafControl = wpGroup.get('waf_enabled');

        if (this.hasInstallControl) {
            this.setupAdminMode(wpGroup, installControl, wafControl);
            this.setupAiBot(wpGroup);
        } else if (wafControl) {
            this.setupUserMode(wafControl);
        }
    }

    ngOnDestroy() {
        this.isDestroyed = true;
        this.destroyed.next();
    }

    private setupAdminMode(
        wpGroup: FormGroup,
        installControl: AbstractControl | null,
        wafControl: AbstractControl | null,
    ) {
        if (!installControl || !wafControl) {
            this.trackSavedConfig(wpGroup, installControl, wafControl);
            return;
        }

        const applyWaf = () => {
            if (this.isDestroyed) return;
            this.applyDisable(wafControl, !!installControl.value);
        };
        // ExtendFormControlNameDirective auto-enables the control via a
        // microtask in its ngOnInit; defer the initial disable into a
        // macrotask so it lands after that microtask.
        this.scheduleInitial(applyWaf);
        installControl.valueChanges
            .pipe(takeUntil(this.destroyed))
            .subscribe(applyWaf);

        this.trackSavedConfig(wpGroup, installControl, wafControl);
    }

    // Reacts to the config stream for two backend-driven concerns:
    //  - savedWafEnabled mirrors the persisted waf_enabled (drives the warning);
    //  - waf_default is backend-gated — its control (and toggle) only exist when
    //    the agent reports the key. Both survive the form rebuild ConfigDirective
    //    does on every (re)init and the config re-push after each save.
    private trackSavedConfig(
        wpGroup: FormGroup,
        installControl: AbstractControl | null,
        wafControl: AbstractControl | null,
    ) {
        const recompute = () => {
            const wafDefaultControl = wpGroup.get('waf_default');
            if (this.isDestroyed || !wafDefaultControl || !installControl || !wafControl) return;
            this.applyDisable(
                wafDefaultControl,
                !!installControl.value && !!wafControl.value,
            );
        };

        if (installControl && wafControl) {
            installControl.valueChanges.pipe(takeUntil(this.destroyed)).subscribe(recompute);
            wafControl.valueChanges.pipe(takeUntil(this.destroyed)).subscribe(recompute);
            this.scheduleInitial(recompute);
        }

        this.configRef?.configChange.pipe(
            takeUntil(this.destroyed),
        ).subscribe((config: { WORDPRESS?: Record<string, unknown> }) => {
            const wordpress = config.WORDPRESS ?? {};
            this.savedWafEnabled = wordpress.waf_enabled !== false;
            if ('waf_default' in wordpress && !wpGroup.get('waf_default')) {
                wpGroup.addControl('waf_default', new FormControl(!!wordpress.waf_default));
            }
            this.scheduleInitial(recompute);
        });
    }

    // All ai_bot_protection controls are backend-gated: an agent config that
    // does not carry a key must never get a control, otherwise saving would POST
    // a field the agent rejects as unknown. Admin mode only: the user-side
    // effective config inherits every admin WORDPRESS option, so key presence
    // there says nothing about the non-root schema, which rejects these fields
    // until per-account support ships. The preset and the admin-only default
    // follow the enable toggle, which follows the install plugin.
    private setupAiBot(wpGroup: FormGroup) {
        wpGroup.get('security_plugin_enabled')?.valueChanges
            .pipe(takeUntil(this.destroyed))
            .subscribe(() => this.recomputeAiBot());

        this.configRef?.configChange.pipe(
            takeUntil(this.destroyed),
        ).subscribe((config: { WORDPRESS?: Record<string, unknown> }) => {
            this.ensureAiBotControls(wpGroup, config.WORDPRESS ?? {});
            this.scheduleInitial(() => this.recomputeAiBot());
        });
    }

    private ensureAiBotControls(wpGroup: FormGroup, wordpress: Record<string, unknown>) {
        if ('ai_bot_protection' in wordpress && !wpGroup.get('ai_bot_protection')) {
            const control = new FormControl(!!wordpress.ai_bot_protection);
            wpGroup.addControl('ai_bot_protection', control);
            control.valueChanges
                .pipe(takeUntil(this.destroyed))
                .subscribe(() => this.recomputeAiBot());
        }
        if ('ai_bot_protection_preset' in wordpress && !wpGroup.get('ai_bot_protection_preset')) {
            wpGroup.addControl('ai_bot_protection_preset', new FormControl(
                wordpress.ai_bot_protection_preset ?? AiBotProtectionPreset.balanced,
            ));
        }
        if ('ai_bot_protection_default' in wordpress && !wpGroup.get('ai_bot_protection_default')) {
            wpGroup.addControl(
                'ai_bot_protection_default',
                new FormControl(!!wordpress.ai_bot_protection_default),
            );
        }
    }

    private recomputeAiBot() {
        if (this.isDestroyed) return;
        const wpGroup = this.wordpressGroup;
        const aiBotControl = wpGroup?.get('ai_bot_protection');
        if (!wpGroup || !aiBotControl) return;

        const installOn = this.installPluginEnabled;
        this.applyDisable(aiBotControl, installOn);

        const dependentEnabled = installOn && !!aiBotControl.value;
        const presetControl = wpGroup.get('ai_bot_protection_preset');
        if (presetControl) this.applyDisable(presetControl, dependentEnabled);
        const defaultControl = wpGroup.get('ai_bot_protection_default');
        if (defaultControl) this.applyDisable(defaultControl, dependentEnabled);
    }

    private setupUserMode(wafControl: AbstractControl) {
        this.wafState$.pipe(
            takeUntil(this.destroyed),
        ).subscribe(state => {
            if (state.disabled) {
                wafControl.setValue(false, { emitEvent: false });
                wafControl.disable({ emitEvent: false });
                wafControl.markAsPristine();
            } else {
                wafControl.enable({ emitEvent: false });
            }
        });
    }

    private applyDisable(control: AbstractControl, enabled: boolean) {
        if (enabled) {
            control.enable({ emitEvent: false });
        } else {
            control.disable({ emitEvent: false });
        }
    }

    private scheduleInitial(fn: () => void) {
        setTimeout(fn, 0);
    }
}
