import { MaliciousItemInBackend, MaliciousFileStatus } from '@imunify360-api/malicious';

export function getVisibleStatusPills(
    counts: Record<string, number>,
    order: string[],
): string[] {
    return order.filter(key => (counts[key] || 0) > 0);
}

export function countStatusGroups(
    statusCounts: Record<string, number>,
    groups: Record<string, string[]>,
): Record<string, number> {
    const result: Record<string, number> = {};
    Object.keys(groups).forEach(key => {
        result[key] = groups[key].reduce(
            (sum, status) => sum + (statusCounts[status] || 0),
            0,
        );
    });
    return result;
}

export function getFixedCount(maliciousItems: MaliciousItemInBackend[]): number {
    let count = 0;
    const fixedStatuses = [
        MaliciousFileStatus.cleanup_done,
        MaliciousFileStatus.cleanup_removed,
        MaliciousFileStatus.quarantined,
    ];

    maliciousItems?.forEach(item => {
        if (fixedStatuses.includes(item.status)) {
            count++;
        }
    });

    return count;
}
